  'sl.sim.timeline': '時間軸', 'sl.sim.tl': { remove: ['既有密封膠撤去', '刀切、拉出、小口面削除'], clean: ['目地清掃', '刷除切粉、塵土；確認乾燥'], backer: ['背襯材裝填', '調整深度、確保二面接著'], tape: ['遮蔽膠帶', '緊貼目地邊、壓實'], prime: ['專用底漆', '{primer} 刷塗，均勻無遺漏'], open: ['底漆乾燥', '≥ 15 min（冬 ≥ 30 min）；當日未打膠須重塗'], fill: ['填充・抹刀壓平', '連續打膠、兩次壓平'], untape: ['撕除膠帶', '表面硬化前'], skin: ['指觸乾燥', '{skin}；之後不沾塵、耐輕雨†'], wait: ['等待', ''], night: ['隔夜', ''], paint: ['可塗裝', '完全硬化後（{cure}）；冬季延長'], full: ['完全硬化・防水效果', '{cure}；接觸水前 7 天'] },
  'sl.sim.k': [['作業完成', '撕除膠帶'], ['指觸乾燥', '不沾塵'], ['完全硬化', '防水・塗裝']], 'sl.sim.day': '第 {d} 天', 'sl.sim.verdict': '{len} m 的接縫，{crew} 人：作業 {work}，{finish} 撕除膠帶；指觸乾燥 {skinAt}；完全硬化 {fullAt}（{cond}）。', 'sl.sim.ok': '當日完成作業', 'sl.sim.late': '作業跨日', 'sl.sim.paintNote': '101A-NB 的塗裝：密封膠充分硬化後（依季節，冬季更長）；塗料與密封膠的組合須先確認附著性。', 'sl.sim.msNote': '同一天不得使用矽利康・變性矽利康（醇類氣體使聚氨酯硬化不良）；CLIO NEO 在變性矽利康施工後隔 1 天以上再施工。',
