SL_STEPS.zh = {
  planS: { tag: '規劃', title: '現況調查：既有密封膠與目地形狀', short: '確認既有密封膠的種類與劣化（硬化、瘦縮、龜裂、剝離）、目地寬度是否因牆板收縮而擴大、小口面狀態；決定打替範圍。', overview: '窯業系外牆板的翻新以「撤去打替」為原則：既有密封膠全部撤去後重新施作。調查時看四件事：既有密封膠的種類（矽利康系會影響新密封膠的硬化）、劣化程度、目地寬度（新建時 10 mm 的目地在收縮後可能擴大——需補背襯材確保二面接著）、外牆材小口的吸水與劣化。', points: ['既有密封膠種類記錄下來：矽利康・變性矽利康系與聚氨酯不同日施工。', '目地寬度與深度量測：保證對象為寬 10–20 mm、深 8–15 mm。', '撤去困難的部位（窗框周圍、入隅）只能增打——增打不在保證範圍，事前向業主說明。', '接縫長度帶入本頁的估算報價。'], src: '標準施工規範 R03 §1・§3' },
  checkS: { tag: '施工前確認', title: '天候、材料與工事記錄用紙', short: '晴或陰；氣溫 0 °C 以上、濕度 85% 以下（保證檢核 5–35 °C、≤ 80%）；風不揚塵。色號、數量、底漆備妥；準備工事記錄用紙。', overview: '步驟 01：確認天候（晴天或陰天；氣溫 0 °C 以上、濕度 85% 以下；注意風）與材料（色、數量是否依指定；底漆是否備妥），並準備所定的工事記錄用紙填寫必要事項。保證檢核表的基準更嚴：氣溫 5–35 °C、相對濕度 80% 以下、避免雨天與朝露未乾。', points: ['晴天或陰天；無降雨風險。', '氣溫 0 °C 以上、濕度 85% 以下（施工要領）；保證檢核：5–35 °C、≤ 80% RH。', '色號、數量依指定；底漆 OP-2019 備妥。', '工事記錄用紙（施工紀錄及檢核表）備妥。'], warning: '指定以外的材料不得使用；保證對象僅限非工作縫（Non-Working Joint）。', src: '標準施工規範 R03 步驟 01；施工紀錄及檢核表' },
  removeS: { tag: '撤去', title: '既有密封膠撤去', short: '以刀沿密封膠兩側切開、拉出，再以起子等削除小口面殘留；三面接著者以一字起子刮除。', overview: '步驟 02：使用美工刀等撤去既有密封膠；必要時以研磨機、起子等工具完全撤去；三面接著的情形以一字起子刮除。外牆材小口面若殘留既有密封膠或既有底漆，接著強度會下降、造成剝離——小口面薄薄削除、仔細撤去。', points: ['刀沿密封膠左右兩面切開。', '以起子等拉出密封膠。', '小口面殘留的密封膠仔細除去（薄削）。', '窗框周圍等撤去困難處：部分撤去後增打（不在保證範圍）。'], warning: '殘留的舊密封膠、舊底漆是剝離的原因。', src: '標準施工規範 R03 步驟 02' },
  cleanS: { tag: '清掃', title: '目地清掃', short: '以刷、毛刷除去切粉、垃圾；被著面不得殘留垃圾、油分、水分。禁用含醇溶劑。', overview: '步驟 03：以刷子或毛刷除去切粉、垃圾等。被著面殘留垃圾、油分、水分是密封膠剝離的原因。使用含醇類的溶劑會造成密封膠未硬化——禁止。', points: ['刷除切粉、塵土。', '被著面無垃圾、油分、水分。', '禁用含醇溶劑。'], warning: '含醇溶劑 → 聚氨酯硬化不良。', src: '標準施工規範 R03 步驟 03' },
  cleanW: { tag: '清掃', title: '窗框周圍的清掃', short: '窗框與外牆材的接著面除去塵土、油分、水分；框體的保護膜撕除；禁用含醇溶劑。', overview: '新建的窗框周圍：撕除框體的保護膜，被著面（鋁框、外牆材小口）以刷除去塵土；油分以不含醇的清潔劑處理†；確認乾燥。', points: ['被著面無垃圾、油分、水分。', '保護膜撕除†。', '禁用含醇溶劑。'], practice: [1], src: '標準施工規範 R03 步驟 03；一般實務†' },
  cleanP: { tag: '清掃', title: '混凝土・PCa・ALC 目地的清掃', short: '目地內的脫模劑、浮漿、粉塵刷除；必要時研磨露出堅實面†；確認乾燥、無油分。', overview: '混凝土與 PCa 板的接著面常有脫模劑與浮漿：刷除粉塵，必要時以研磨露出堅實面†。含水的下地在硬化途中釋出水蒸氣會使密封膠隆起、破裂——施工前確保完全乾燥。', points: ['刷除粉塵、浮漿；必要時研磨†。', '確認乾燥、無油分。', '禁用含醇溶劑。'], warning: '下地含水 → 密封膠隆起、破裂（TDS）。', practice: [0], src: 'TDS 重要資訊；標準施工規範 R03 步驟 03' },
  cleanV: { tag: '清掃', title: '貫穿部周圍的清掃', short: '通氣蓋、百葉、電箱的凸緣與周圍外牆面除去塵土、油分；確認材質（鍍膜鋁◎、PVC◎、不鏽鋼△）。', overview: '貫穿部的被著面材質多樣：依 TDS 的部材適應性表確認（鍍膜鋁、PVC 板、FRP 為◎；不鏽鋼△）。除去塵土與油分，確認乾燥。', points: ['凸緣與外牆面除去塵土、油分。', '材質對照 OP-2020 適應性表。', '禁用含醇溶劑。'], src: 'CLIO NEO TDS 各類部材適應性' },
  cleanQ: { tag: '清掃', title: '水處理構造物接縫的清掃', short: '接縫內的浮漿、油污刷除；完全乾燥後施工——含水的混凝土會使密封膠隆起。', overview: '淨水場、水池、箱涵的接縫多半潮濕：先讓下地完全乾燥（含水的下地在硬化途中釋出水蒸氣，密封膠隆起、破裂），刷除浮漿與粉塵。', points: ['刷除浮漿、粉塵；除去油污。', '完全乾燥後施工。', '禁用含醇溶劑。'], warning: '施工前確保基底完全乾燥不含水氣（TDS）。', src: 'TDS 重要資訊' },
  backerS: { tag: '背襯材', title: '背襯材裝填：目地形狀與二面接著', short: '確認目地寬、深；以背襯材調整深度（寬 10–20 mm 對應深 8–15 mm，深度 ≤ 寬度，厚 ≥ 5 mm），同時確保二面接著；舊 bond breaker 撕除重貼。', overview: '步驟 04：確認目地寬度、深度是否適正。保證對象的目地形狀：寬 10 mm 以上 20 mm 以下，深 8 mm 以上 15 mm 以下（深度不得超過寬度；考量外牆板花紋凹凸與抹刀壓入，密封膠厚度 5 mm 以上）——以背襯材調整。背襯材同時完成目地形狀的調整與二面接著。舊的 bond breaker 撕除後重貼。工作縫必須二面接著：三面接著是切斷、剝離的原因；外牆材收縮使目地擴大時，以背襯材填塞縫隙確保二面接著。', points: ['量測寬、深；不在範圍內先調整。', '背襯材壓入目地底至所需深度。', '三面接著不可（工作縫）；非工作縫亦可適用。', '目地擴大時補背襯材。'], warning: '密封膠厚度未達 5 mm 不在保證範圍。', src: '標準施工規範 R03 步驟 04' },
  backerW: { tag: '背襯材', title: '窗框周圍的背襯材', short: '窗框與外牆材之間以背襯材調整深度、確保二面接著；轉角處背襯材連續不斷。', overview: '窗框周圍的目地在轉角處最容易失敗：背襯材連續繞過轉角，深度依寬度調整（10–20 mm 寬 → 8–15 mm 深）。', points: ['背襯材連續繞過四個轉角。', '深度 ≤ 寬度、厚 ≥ 5 mm。'], src: '標準施工規範 R03 步驟 04' },
  backerP: { tag: '背襯材', title: '寬目地的背襯材', short: 'PCa／RC 的 20 mm 寬目地：背襯材直徑約寬 × 1.3†，壓入至深 15 mm；確保二面接著。', overview: '寬 20 mm 的伸縮縫：深度以背襯材控制在 15 mm 以內（深度不得大於寬度）；背襯材直徑約目地寬的 1.3 倍†，壓入時不扭轉、不破壞表皮†。', points: ['直徑約寬 × 1.3†。', '壓入至深 15 mm；表面平整。', '二面接著。'], practice: [0, 1], src: '標準施工規範 R03 步驟 04；一般實務†' },
  tapeS: { tag: '遮蔽膠帶', title: '遮蔽膠帶貼付', short: '使用不殘膠的膠帶，緊貼目地邊壓實；依花紋凹凸壓密不浮起；被著面乾燥後才貼。', overview: '步驟 05：使用不在被著面殘留黏著劑的膠帶；緊貼目地邊仔細壓實；配合花紋凹凸壓密避免浮起；確認被著面乾燥後作業。膠帶離目地邊太遠時密封膠形成薄層殘留，化妝目地會白化。', points: ['不殘膠的膠帶。', '緊貼目地邊、壓實、無浮起。', '被著面乾燥後貼。'], src: '標準施工規範 R03 步驟 05' },
  tapeV: { tag: '遮蔽膠帶', title: '貫穿部周圍的遮蔽', short: '沿凸緣與外牆面貼膠帶，留出約 10 mm 的填角寬；曲線處以短段膠帶接續†。', overview: '透明密封膠的收邊寬度要一致：沿凸緣邊與外牆面各貼一道膠帶，留出填角寬度（約 10 mm）；圓形通氣蓋以短段膠帶接續†。', points: ['填角寬度一致。', '曲線以短段接續†。'], practice: [1], src: '標準施工規範 R03 步驟 05；一般實務†' },
  primeS: { tag: '底漆', title: '專用底漆 OP-2019 塗布', short: '必用 OP-2019；被著面無污、無油、乾燥後均勻塗布，無塗斑、無漏塗；乾燥 15 分鐘以上（冬季 30 分鐘以上）；當日未打膠或淋濕須重塗。', overview: '步驟 06：必須使用底漆 OP-2019（適用範圍：窯業系外牆板、樹脂窗框、鋁窗框）。確認被著面無污染、無油分、充分乾燥後塗布；無塗斑、無遺漏、無漏塗。塗布後乾燥 15 分鐘以上（冬季 30 分鐘以上）＝ 開放時間。底漆塗布後當日未能打膠，或打膠前被著面被雨淋濕時，確認乾燥後重塗。塗布量參考：目地單側 50 cm 一往復沾一次刷。', points: ['使用 {OP2019}。', '均勻塗布，無塗斑、無漏塗；被著面以外不沾。', '乾燥 ≥ 15 min（冬 ≥ 30 min）。', '當日未打膠或淋濕 → 重塗。', 'PP、PE 不接著，不可用。'], ordered: true, warning: '底漆未乾或過量 → 溶劑揮發使密封膠隆起、破裂。', src: '標準施工規範 R03 步驟 06；OP-2019 TDS' },
  primeN: { tag: '底漆', title: '專用底漆 OP-2020 塗布（101A-NB）', short: '101A-NB 的專用底漆 OP-2020（或 OP-2019）：被著面乾燥後均勻塗布，乾燥 15–30 分鐘後填充。', overview: '101A-NB 可在無底漆狀態下接著，但強烈建議使用底漆以確保完整接著性：TDS 部材適應性表的各類部材皆可用 OP-2020 或 OP-2019。乾固時間 15–30 分鐘。', points: ['使用 {OP2020}（或 {OP2019}）。', '均勻塗布，無漏塗。', '乾燥 15–30 min 後填充。'], ordered: true, warning: '底漆未乾或過量 → 密封膠隆起、破裂。', src: '101A-NB TDS 部材準備；OP-2020 TDS' },
  primeC: { tag: '底漆', title: '專用底漆 OP-2020 塗布（CLIO NEO）', short: 'CLIO NEO 的專用底漆 OP-2020：鍍膜鋁、PVC、FRP 等被著面均勻塗布，乾燥 15–30 分鐘。', overview: 'CLIO NEO 的物性數據皆以 OP-2020 底漆為前提（H 型試片、破壞狀況 CF）。被著面乾燥後均勻塗布，乾固 15–30 分鐘後填充。', points: ['使用 {OP2020}。', '均勻塗布，無漏塗。', '乾燥 15–30 min。'], ordered: true, src: 'CLIO NEO TDS；OP-2020 TDS' },
  fillS: { tag: '填充', title: '密封膠填充 EXCEED', short: '確認底漆開放時間已過；噴嘴前端抵住目地底，不中斷地連續打膠；適量填充、不夾氣泡。', overview: '步驟 07：確認底漆塗布後的開放時間已經過；噴嘴前端抵住目地底，不間斷地持續打膠；不夾入氣泡地適量填充。密封膠要確實填充到目地底，內部與底部不留空洞——空洞內的空氣或水氣膨脹會造成隆起、破裂。', points: ['底漆開放時間已過。', '噴嘴抵住目地底，連續打膠。', '適量、不夾氣泡、不留空洞。', '開封當天用完。'], warning: '空洞 → 隆起、破裂。', src: '標準施工規範 R03 步驟 07；TDS' },
  fillW: { tag: '填充', title: '窗框周圍的填充', short: '沿窗框四邊連續打膠，轉角不中斷；上緣先打†；噴嘴抵住目地底。', overview: '窗框周圍：噴嘴抵住目地底，沿四邊連續打膠、轉角處不中斷、不夾氣泡。', points: ['轉角連續。', '適量、不夾氣泡。'], src: '標準施工規範 R03 步驟 07' },
  fillP: { tag: '填充', title: '寬目地的填充', short: '20 mm 寬目地：噴嘴抵住背襯材面，慢速連續打膠填滿，不留空洞；深 15 mm。', overview: '寬目地容易在背襯材兩側夾空氣：噴嘴抵住背襯材面慢速打膠，讓密封膠由底部向上填滿。', points: ['噴嘴抵住背襯材面。', '慢速連續，填滿至膠帶面。'], src: '標準施工規範 R03 步驟 07' },
  fillN: { tag: '填充', title: '密封膠填充 101A-NB', short: '底漆乾燥後，噴嘴抵住目地底連續打膠、不留空洞；之後要塗裝的目地表面抹平即可。', overview: '101A-NB 的填充要領與 EXCEED 相同：底漆乾燥後連續打膠、不留空洞；標準填縫的最大深度 15 mm、最小 8 mm，最大寬度 20 mm、最小 10 mm，深度不得大於寬度。', points: ['連續打膠、不留空洞。', '寬 10–20 mm、深 8–15 mm。'], src: '101A-NB TDS 重要資訊' },
  fillC: { tag: '填充', title: '透明密封膠填充 CLIO NEO', short: '沿凸緣周圍連續打出約 10 × 10 mm 的填角；透明，厚塗仍可透視。', overview: 'CLIO NEO 在 10 mm 厚度仍保持透明——可以打出足夠厚度的填角做確實的防水，不必為了透明而薄塗。', points: ['連續打膠繞一圈。', '填角約 10 × 10 mm。'], src: 'CLIO NEO 型錄' },
  fillQ: { tag: '填充', title: '水處理構造物接縫的填充', short: '底漆乾燥後連續打膠、不留空洞；深 15 mm；完全硬化 7 天後才接觸水。', overview: '接觸水的接縫：填實不留空洞（浸水後空洞內的水會造成剝離）；TDS 要求 7 天固化時間以達完全防水效果。', points: ['連續打膠、不留空洞。', '通水前養生 7 天（23 °C）。'], src: '101A-NB TDS' },
  toolS: { tag: '抹刀壓平', title: '抹刀壓平：兩次', short: '第一次把密封膠壓入目地底、趕出氣泡並使之密貼被著面；第二次把表面抹平。壓不足會接著不良。', overview: '步驟 08：抹刀壓平以兩次為基本——第一次把密封膠壓入，第二次把表面壓平，就能漂亮收尾。朝目地底充分壓入，消除間隙、趕出氣泡；使密封膠均勻密貼被著面，確保接著強度。壓不足時不密貼被著面，造成接著不良。', points: ['第一次：壓入、趕氣泡。', '第二次：抹平。', '朝目地底充分壓入。'], warning: '壓不足 → 接著不良。', src: '標準施工規範 R03 步驟 08' },
  toolV: { tag: '抹刀壓平', title: '填角的抹平', short: '以抹刀把填角壓成一致的三角斷面，密貼凸緣與牆面；透明材的氣泡會被看見——第一次壓入要確實。', overview: '透明密封膠的氣泡與空洞會被看見：第一次壓入要確實趕出氣泡，第二次抹平成一致的三角斷面。', points: ['第一次：壓入、趕氣泡。', '第二次：抹平成一致斷面。'], src: '標準施工規範 R03 步驟 08' },
  untapeS: { tag: '撕膠帶', title: '遮蔽膠帶除去', short: '在密封膠表面硬化前，不弄髒周邊地小心撕除；硬化後撕會拉絲、損及目地邊的收尾。', overview: '步驟 09：在密封膠表面硬化前，注意不要弄髒周邊，小心撕除膠帶。表面硬化進行後再撕，增黏的密封膠會拉絲，目地邊等的收尾受損。', points: ['表面硬化前撕除。', '不弄髒周邊。'], warning: '硬化後撕 → 拉絲、收尾受損。', src: '標準施工規範 R03 步驟 09' },
  paintN: { tag: '塗裝', title: '密封膠上的塗裝', short: '一液聚氨酯自表面起硬化，表面硬化時間隨季節大幅變動——充分硬化後才塗裝，冬季延長；用彈性塗料，先確認附著性。', overview: '§6：EXCEED／101A-NB 是一成分形聚氨酯密封膠，與空氣中水分反應自表面起硬化；表面硬化（乾燥）時間依季節（溫度、濕度）大幅變動，冬季尤其費時——密封膠充分硬化後再塗裝。密封膠上的塗料有施工直後或經時龜裂的可能：依「密封膠＋塗料」的組合，附著性可能偏低或塗料表面發黏，請確認後使用。101A-NB 可適用大多類型塗料，但使用無彈性塗料時可能因密封膠的柔軟與伸縮而龜裂。', points: ['充分硬化後塗裝；冬季延長。', '彈性塗料；先試塗確認附著。', '無彈性塗料 → 塗膜龜裂。'], src: '標準施工規範 R03 §6；101A-NB TDS' },
  inspS: { tag: '檢查・清掃', title: '點檢與清掃、施工紀錄', short: '外牆面沾到的密封膠、底漆在硬化前以布擦除；確認目地飽滿、無空洞、無漏打；填寫施工紀錄及檢核表（LOT、目地尺寸、底漆、完工照片）。', overview: '步驟 10：外牆材表面沾到的密封膠或底漆在硬化前以布擦除——擦拭不足會造成變色、污染附著。同時完成保證的紀錄：密封膠色號、LOT 與數量、底漆 LOT 與罐數、含 LOT 的產品照片、目地寬深多處量尺照片、底漆塗布多處照片、完工多處照片、特記事項。', points: ['硬化前擦除沾污。', '目視：飽滿、無空洞、無漏打、無氣泡。', '施工紀錄及檢核表填寫並簽名。'], src: '標準施工規範 R03 步驟 10；施工紀錄及檢核表' },
  inspV: { tag: '檢查', title: '透明收邊的檢查', short: '透明材的氣泡、空洞、漏打一眼可見；沾到周邊的密封膠硬化前擦除。', overview: 'CLIO NEO 是透明的：氣泡與空洞會被看見，也是防水的弱點。檢查後硬化前擦除周邊沾污。', points: ['無氣泡、無空洞。', '硬化前擦除沾污。'], src: '標準施工規範 R03 步驟 10' },
  cureS: { tag: '養生', title: '養生與硬化', short: '指觸乾燥 5 h（23 °C）／24 h（5 °C）；完全硬化 3–7 天／17–21 天；完全防水效果需 7 天。施工日避開降雨。', overview: '一液濕氣硬化型：硬化過程需接觸空氣中的水分。指觸乾燥 5 小時（23 °C）、24 小時（5 °C）；完全硬化 3–7 天（23 °C）、17–21 天（5 °C）；確保 7 天固化時間以達完全防水效果。低溫時延長，計畫塗裝、通水在完全硬化之後。', points: ['指觸乾燥 5 h／24 h。', '完全硬化 3–7 天／17–21 天。', '完全防水效果：7 天。'], src: 'EXCEED／101A-NB TDS 施作參考' },
  cureQ: { tag: '養生', title: '通水前的養生：7 天', short: '完全硬化前不得接觸水；TDS 要求 7 天固化時間以達完全防水效果；低溫延長。', overview: '接觸水的接縫：養生 7 天（23 °C）後通水；5 °C 時完全硬化 17–21 天。', points: ['7 天後通水（23 °C）。', '低溫延長至完全硬化。'], src: '101A-NB TDS' },
  planW: { tag: '規劃', title: '窗框周圍：新建一次做對', short: '窗框材質（鋁陽極氧化、鍍膜、樹脂）與外牆材小口的接著性確認；目地寬 10–20 mm；翻新時只能增打。', overview: '窗框周圍的目地承受最多雨水，翻新時難以完全撤去（勉強撤去會傷及周邊部材），只能部分撤去後增打——增打不在保證範圍。新建時把目地寬度留在 10–20 mm、用對底漆，是最划算的做法。', points: ['材質對照 OP-2019 適應性：陽極氧化鋁◎、鍍膜鋁◎、PVC◎。', '目地寬 10–20 mm、深 8–15 mm。', '翻新：部分撤去＋增打（保證對象外）。'], src: '標準施工規範 R03 §3 案例 01；OP-2019 TDS' },
  planP: { tag: '規劃', title: 'PCa／RC 目地：動的大小與保證的邊界', short: '伸縮縫、誘發縫的寬度與預期伸縮（±25% 以內）；非工作縫在保證範圍，工作縫（帷幕牆）依設計另議。', overview: 'EXCEED 的用途包含各種建築物的工作縫（伸縮目地）與混凝土誘發縫；製造商的專案限定保證則以非工作縫（RC 構造體目地等）為對象，工作縫（帷幕牆等）不在保證範圍。設計時：目地寬 10–20 mm、預期伸縮在 ±25% 以內，混凝土面用 OP-2019。', points: ['預期伸縮 ≤ ±25%。', '寬 10–20 mm、深 8–15 mm。', '保證：非工作縫；工作縫另議。'], src: 'EXCEED TDS；標準施工規範 R03 §1；保證書' },
  planA: { tag: '規劃', title: '要塗裝的目地：選 101A-NB', short: '之後要整面塗裝的 ALC、混凝土目地：不含可塑劑的 101A-NB（塗料附著性優異）；塗裝在密封膠硬化之後。', overview: '含可塑劑的密封膠在塗裝後數月就可能滲出、發黏、積塵，毀掉整面外牆的外觀。101A-NB 不含可塑劑，塗料附著性優異、塗料適應廣——是需要塗裝的目地的標準答案。ALC 對底漆為△，設計時留意。', points: ['101A-NB ＋ OP-2020。', '塗裝在充分硬化後；彈性塗料。', 'ALC：接著性△，先試驗†。'], practice: [2], src: '101A-NB 型錄・TDS' },
  planV: { tag: '規劃', title: '貫穿部：透明收邊', short: '通氣蓋、百葉、風管、電箱的材質確認；CLIO NEO 不必配色；變性矽利康施工後隔 1 天。', overview: 'CLIO NEO 是外裝用高透明・高耐候密封膠，適用於百葉、通氣蓋、風管、電箱等的防水處理；不適用於外牆板板間目地（伸長 243%）。材質依 OP-2020 適應性表；現場有變性矽利康施工時隔 1 天以上。', points: ['材質：鍍膜鋁◎、PVC◎、FRP◎、不鏽鋼△。', '不用於板間目地。', '變性矽利康後隔 1 天以上。'], src: 'CLIO NEO 型錄・TDS' },
  planQ: { tag: '規劃', title: '水處理構造物：證據先行', short: '接觸自來水的接縫：101A-NB 的 SGS 自來水接觸試驗（2019）與 ASTM C920 Class 50 報告可直接送審；通水前養生 7 天。', overview: '101A-NB 在彰濱淨水場新建工程通過 SGS 的汙染性（JIS A 5754）、耐臭氧（CNS 8904）與自來水溶出試驗；在台北捷運環狀線 CF640 箱涵接縫以 ASTM C920-11 Class 50 檢驗合格。規範時附上報告；施工時養生 7 天後通水。', points: ['報告：SGS HV-19-00384、GSL PO-14-01052C、SGS KZ-19-00945。', '寬 10–20 mm、深 8–15 mm。', '通水前 7 天養生。'], src: 'SGS／GSL 試驗報告；101A-NB TDS' }
};
SLV_T.zh = { classes: SLT.zh['sl.vs.classes'], rows: SLT.zh['sl.vs.rows'], rowsH: SLT.zh['sl.vs.rowsH'], bars: SLT.zh['sl.vs.bars'], aud: SLT.zh['sl.vs.aud'], honest: SLT.zh['sl.vs.honest'], src: SLT.zh['sl.vs.src'], label: SLT.zh['sl.vs.label'], title: SLT.zh['sl.vs.title'], sub: SLT.zh['sl.vs.sub'], fair: SLT.zh['sl.fair'], cardH: SLT.zh['sl.vs.cardH'], tag: SLT.zh['sl.vs.tag'], vsTag: SLT.zh['sl.vs.vsTag'], kpi: SLT.zh['sl.vs.kpi'], barsLow: SLT.zh['sl.vs.barsLow'], barsHigh: SLT.zh['sl.vs.barsHigh'], barsAlt: SLT.zh['sl.vs.barsAlt'], barsNA: SLT.zh['sl.vs.barsNA'], matrixTitle: SLT.zh['sl.vs.matrixTitle'], matrixSub: SLT.zh['sl.vs.matrixSub'] };


